CREATE TABLE `folders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `assigned_user_id` bigint(20) unsigned DEFAULT NULL,
  `color` varchar(20) NOT NULL DEFAULT '#4f46e5',
  `is_favorite` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `folders_uuid_unique` (`uuid`),
  KEY `folders_department_id_foreign` (`department_id`),
  KEY `folders_created_by_foreign` (`created_by`),
  KEY `folders_parent_id_name_index` (`parent_id`,`name`),
  KEY `folders_assigned_user_id_index` (`assigned_user_id`),
